import{_ as e,o as f,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"التعليم والمدارس","description":"كيف تجد الأسر الوافدة المدارس الحكومية والخاصة في قطر وتسجل أبناءها فيها، ومن يحق له الالتحاق، والمستندات، والرسوم، والتقويم المدرسي.","frontmatter":{"title":"التعليم والمدارس","description":"كيف تجد الأسر الوافدة المدارس الحكومية والخاصة في قطر وتسجل أبناءها فيها، ومن يحق له الالتحاق، والمستندات، والرسوم، والتقويم المدرسي.","lastChecked":"2026-10","sourceCount":9},"headers":[],"relativePath":"ar/guide/education.md","filePath":"ar/guide/education.md"}'),t={name:"ar/guide/education.md"};function s(l,a,n,i,c,h){return f(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="التعليم-والمدارس" tabindex="-1">التعليم والمدارس <a class="header-anchor" href="#التعليم-والمدارس" aria-label="Permalink to &quot;التعليم والمدارس&quot;">​</a></h1><p>في قطر مدارس حكومية ومدارس خاصة، وتشرف عليها جميعًا وزارة التربية والتعليم والتعليم العالي. والقبول في المدارس الحكومية مقصور على فئات محددة، فتحقق أولًا من أن ابنك ضمنها.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>أرقام التواصل العامة مع الوزارة هي 155 و4404 4444.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="من-يحق-له-الالتحاق-بالمدارس-الحكومية" tabindex="-1">من يحق له الالتحاق بالمدارس الحكومية <a class="header-anchor" href="#من-يحق-له-الالتحاق-بالمدارس-الحكومية" aria-label="Permalink to &quot;من يحق له الالتحاق بالمدارس الحكومية&quot;">​</a></h2><p>تحدد الوزارة الفئات التالية:<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></p><ul><li>أبناء القطريين والقطريات ومواطني دول مجلس التعاون.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>أبناء المقيمين العاملين في القطاعات الحكومية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>أبناء العاملين في المؤسسات الخيرية الخاصة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>أبناء حاملي الإقامة الدائمة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li></ul><p>أما أبناء المقيمين العاملين في القطاع الخاص فمسارهم أضيق: خصصت الوزارة لهم 18 مدرسة في المناطق والقرى البعيدة. ويلزمك إثبات سكنك الفعلي هناك، مثل عقد إيجار موثق أو شهادة كهرباء باسم ولي الأمر.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> وعلى غير الناطقين بالعربية من هذه الفئة اجتياز اختبار في اللغة العربية، وقد يلتحقون ببرنامج علاجي في العربية، ولا يُسمح لاحقًا بالتحويل إلى مدرسة حكومية في الدوحة أو المناطق الحضرية الأخرى.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="التسجيل-في-مدرسة-حكومية" tabindex="-1">التسجيل في مدرسة حكومية <a class="header-anchor" href="#التسجيل-في-مدرسة-حكومية" aria-label="Permalink to &quot;التسجيل في مدرسة حكومية&quot;">​</a></h2><ol><li>استخدم نظام &quot;أين مدرستي؟&quot; لمعرفة المدرسة المناسبة لعنوان سكنك.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>ادخل إلى بوابة معارف واختر خدمة التسجيل في المدارس الحكومية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>إذا كان النظام مغلقًا، فقدم الطلب يدويًا في مدرسة ضمن منطقتك، ويتوقف القبول على توفر المقاعد الشاغرة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li></ol><p>جهز هذه المستندات: البطاقة الشخصية القطرية للطالب، وشهادة الميلاد، والملف الصحي. ويلزم لأبناء المقيمين أيضًا شهادة عمل.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><p>في العام الدراسي 2026 إلى 2027 فُتح التسجيل لجميع الجنسيات ابتداءً من 24 مايو 2026، ثم أعيد فتحه من 25 أغسطس إلى 1 أكتوبر 2026. وحُسب عمر الطالب في 31 ديسمبر 2026، وكان القبول في الصف الأول لمن ولدوا في 31 ديسمبر 2020 أو قبله.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup> وهذه المواعيد خاصة بذلك العام، فتابع تعميم الوزارة للعام التالي.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></p><h2 id="التسجيل-في-مدرسة-خاصة" tabindex="-1">التسجيل في مدرسة خاصة <a class="header-anchor" href="#التسجيل-في-مدرسة-خاصة" aria-label="Permalink to &quot;التسجيل في مدرسة خاصة&quot;">​</a></h2><ol><li>ابحث في الخريطة التفاعلية للمدارس ورياض الأطفال الخاصة على موقع الوزارة.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li>تواصل مع المدرسة مباشرة، لأن كل مدرسة تسجل الطلبة وفق سياستها.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li>إذا واجهت صعوبة، يمكن لإدارة تراخيص المدارس الخاصة مساعدتك في التسجيل أو في البحث عن مدرسة بديلة.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li></ol><h2 id="الأبناء-القادمون-بتأشيرة-عائلية" tabindex="-1">الأبناء القادمون بتأشيرة عائلية <a class="header-anchor" href="#الأبناء-القادمون-بتأشيرة-عائلية" aria-label="Permalink to &quot;الأبناء القادمون بتأشيرة عائلية&quot;">​</a></h2><p>توفر الوزارة منصة التعليم الإلزامي للأبناء من سن 6 إلى 18 عامًا الذين يحملون تأشيرة عائلية قابلة للتحويل إلى إقامة. ومن خلالها يمكنك التقديم على مدرسة خاصة أو مدرسة حكومية، أو إثبات أن الطالب يدرس خارج قطر أو أن لديه سببًا طبيًا يمنعه من الدراسة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></p><ul><li>يحتاج كل طالب إلى طلب مستقل، ولا يمكنك تقديم أكثر من طلب في الوقت نفسه. وإذا رُفض الطلب يمكنك التقديم على مدرسة أخرى.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li>يعرض النظام المدارس التي فيها مقاعد شاغرة فقط، مع روابط مواقعها لتطلع على الرسوم الدراسية والشروط.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li><li>بعد مراجعة الطلب تتواصل معك المدرسة لتحديد مقابلة للطالب، وقد تدفع رسوم تسجيل وفق سياسة المدرسة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></li><li>تطلب المدارس الدولية شهادة معتمدة رسميًا لآخر صف أتمه الطالب. أما المدارس التي تتبع المعايير الوطنية القطرية فتوجهك أولًا إلى مركز معلومات الطلبة لمعادلة الشهادة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></li><li>بعد حصول الطالب على البطاقة الشخصية القطرية، يُسمح بالتحويل بين المناهج المختلفة حتى نهاية يناير، وضمن المنهج نفسه حتى نهاية فبراير.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></li></ul><p>لا يستخدم أولياء الأمور العاملون في القطاع الحكومي هذه المنصة، إذ تتولى الوزارة تسجيل أبنائهم وفق الشواغر وضوابط القبول.<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3]</a></sup></p><h2 id="الرسوم-المدرسية" tabindex="-1">الرسوم المدرسية <a class="header-anchor" href="#الرسوم-المدرسية" aria-label="Permalink to &quot;الرسوم المدرسية&quot;">​</a></h2><p>أصدرت الوزارة سياسة الرسوم المدرسية للمدارس ورياض الأطفال الخاصة، وهي ملزمة لجميع هذه المدارس. وتهدف إلى ضمان الإفصاح عن الرسوم المعتمدة ومنع تحصيل أي رسوم لم تعتمدها الوزارة مسبقًا.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><p>وتشترط السياسة موافقة الوزارة المسبقة والإفصاح الواضح عن رسوم التشغيل والخدمات والرسوم الاختيارية، ولا يُلزم أولياء الأمور بدفع الرسوم الاختيارية.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup> اطلب من المدرسة الاطلاع على رسومها المعتمدة قبل أن تدفع.<sup class="footnote-ref"><a href="#fn6" id="fnref6:2">[6]</a></sup></p><h2 id="التقويم-المدرسي" tabindex="-1">التقويم المدرسي <a class="header-anchor" href="#التقويم-المدرسي" aria-label="Permalink to &quot;التقويم المدرسي&quot;">​</a></h2><p>بدأ العام الدراسي 2026 إلى 2027 يوم الأحد 30 أغسطس 2026.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup> وتنشر الوزارة التقويم السنوي لكل عام، ويشمل مواعيد الإجازات والاختبارات في المدارس الحكومية.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup> ويثبت التقويم المعتمد للأعوام من 2025 إلى 2028 إجازة منتصف العام في الثلث الأخير من ديسمبر، ويذكر الإعلان أن ذلك يسهم في المواءمة بين إجازات المدارس الحكومية والخاصة.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><p>انظر أيضًا: <a href="./family-visas">التأشيرات العائلية</a>، <a href="./residence-permit-and-qid">الإقامة والبطاقة الشخصية</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/Content/RegistrationPublicShools" target="_blank" rel="noreferrer">التسجيل في المدارس الحكومية</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/News/Details/17391000" target="_blank" rel="noreferrer">تعميم إجراءات تسجيل الطلبة وتحويلهم للعام الدراسي 2026 إلى 2027</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/Content/CompulsoryEducationVisas" target="_blank" rel="noreferrer">التعليم الإلزامي (التأشيرات)</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/Content/Listofprivateschools" target="_blank" rel="noreferrer">قائمة المدارس ورياض الأطفال الخاصة</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/Content/RegistrationPrivateSchool" target="_blank" rel="noreferrer">التسجيل في المدارس الخاصة</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/News/Details/18451800" target="_blank" rel="noreferrer">الوزارة تطلق سياسة الرسوم المدرسية للمدارس ورياض الأطفال الخاصة</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/News/Details/19063800" target="_blank" rel="noreferrer">الوزارة تعلن استكمال استعداداتها للعام الدراسي الجديد</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/en/Content/AnnualCalendar" target="_blank" rel="noreferrer">التقويم السنوي</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn9" class="footnote-item"><p>وزارة التربية والتعليم والتعليم العالي، <a href="https://www.edu.gov.qa/ar/News/Details/14514600" target="_blank" rel="noreferrer">اعتماد التقويم الأكاديمي الجديد للأعوام من 2025 إلى 2028</a>. آخر تحقق: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',26)])])}const d=e(t,[["render",s]]);export{u as __pageData,d as default};
